RE_COD = re.compile(r'^([A-Z]{2,3} [A-Z]{1,4}-\d{3})-(\d{3})$')


def separar_versao(apps, schema_editor):
    """'IT GP-009-000' → codigo 'IT GP-009' + versao '000'; leituras existentes ficam na versão atual."""
    Documento = apps.get_model('acervo', 'Documento')
    DocumentoVisto = apps.get_model('acervo', 'DocumentoVisto')
    for doc in Documento.objects.exclude(codigo=''):
        bases, versoes = [], []
        for parte in doc.codigo.split(' / '):
            m = RE_COD.match(parte.strip())
            if not m:
                break
            bases.append(m.group(1))
            versoes.append(m.group(2))
        else:
            doc.codigo = ' / '.join(bases)
            doc.versao = ' / '.join(versoes)
            doc.save(update_fields=['codigo', 'versao'])
            DocumentoVisto.objects.filter(documento=doc).update(versao=doc.versao)


